  _ = `Käytä keskitason kosketuspalautetta.`,
  _ = `Kosketuspalautteen voimakkuus – Korkea`,
  _ = `Käytä voimakasta kosketuspalautetta.`,
  _ = `Kosketuspalautteen voimakkuus – Käytä aktivaattorin asetuksia`,
  _ = `Kosketuspalautetta hallinnoidaan kunkin aktivaattorin asetuksilla.`,
