  _ = `Komento: Vieritysrulla – Lista 9`,
  _ = `Voit valita ohjaimen lähettämän painalluksen listan yhdeksännen kohdalla.`,
  _ = `Komento: Vieritysrulla – Lista 10`,
  _ = `Voit valita ohjaimen lähettämän painalluksen listan kymmenennen kohdalla.`,
  _ = `Pyöreä lista`,
  _ = `Kun tämä on valittuna ja käyttäjä vierittää vieritysrullan komentolistan kumman tahansa loppupään ohi, listaa jatketaan toiseen päähän. Muuten listan loppupään ohi vieritys ei käynnistä mitään komentoa.`,
  _ = `Pyöreä lista – Päällä`,
  _ = `Listan päät yhdistyvät, jolloin lopusta pääsee alkuun ja alusta loppuun.`,
  _ = `Pyöreä lista – Pois`,
  _ = `Komentojen läpi vieritettäessä, kun listan reuna saavutetaan, lista pysähtyy, eikä ulostuloja lähetetä ennen kuin toinen suunta lähetetään.`,
  _ = `Pyyhkäisyn suunta`,
  _ = `Määrittää, minkälaisilla liikkeillä komentolistaa selataan.`,
  _ = `Pyöreä vieritysrulla`,
  _ = `Vieritysrullaa pyyhkäistään pyörittämällä.`,
  _ = `Tee pyörittävää liikettä liikkuaksesi eteen- tai taaksepäin vieritysrullan komentolistassa.`,
  _ = `Vaakasuora vieritysrulla`,
  _ = `Vieritysrullaa pyyhkäistään vaakasuorasti.`,
  _ = `Pystysuora vieritysrulla`,
  _ = `Vieritysrullaa pyyhkäistään pystysuorasti.`,
  _ = `Käännä pyyhkäisyn suunta`,
  _ = `Kääntää suunnan, johon vieritysrullaa pyyhkäistään, jotta siirrytään "eteenpäin" komentosarjassa.`,
  _ = `Perinteinen vieritysrulla`,
  _ = `Vieritysrullan suuntaa ei käännetä.`,
  _ = `Käänteinen vieritysrulla`,
  _ = `Vieritysrullan suunta käännetään.`,
  _ = `Pyörityksen kitka`,
  _ = `Tämä määrittää kuinka kauan hiirirulla pyörii näpäyttäessä. Alhainen kitka johtaa pitempään pyörähdykseen.`,
  _ = `Rullan kitka – Pois`,
  _ = `Mikäli ei käytössä, vieritysrullalla ei ole liikemäärää. Tämä tarkoittaa, että vieritysrullatila on poistettu käytössä.`,
  _ = `Rullan kitka – Matala`,
  _ = `Matalalla kitkalla pyöräytetty rulla jatkaa pyörimistä pitkään ja pysähtyy hitaasti.`,
  _ = `Rullan kitka – Keskitaso`,
  _ = `Keskitason kitkalla pyöräytetty rulla jatkaa pyörimistä ja pysähtyy hetken kuluttua.`,
  _ = `Rullan kitka – Korkea`,
  _ = `Suurella kitkalla vieritysrulla pyörii hetken ja pysähtyy nopeasti.`,
  _ = `Rullan kitka – Ei kitkaa`,
  _ = `Ilman kitkaa, vieritysrulla pyörii liikautettuna ikuisesti ilman ulkoisia vaikutteita.`,
  _ = `Syöttötapa – Kosketusvalikko`,
